  function hitTarget(x,y){return document.elementsFromPoint(x,y).map(el=>el.closest?.('[data-tc-drop]')).find(Boolean);}
  function highlight(target){root.querySelectorAll('.is-drop-target').forEach(n=>n.classList.remove('is-drop-target'));target?.classList.add('is-drop-target');}
  function updateGesture(x,y){
    const g=gesture;if(!g?.active)return;g.lastX=x;g.lastY=y;
    const target=hitTarget(x,y);g.target=target;highlight(target);
    let label='移到日期、时间轴或收集箱';g.result=null;
    if(g.type==='group'){if(target?.matches('.tc-collection-column[data-tc-drop=group]')&&target.dataset.groupId){const r=target.getBoundingClientRect();g.result={targetId:target.dataset.groupId,after:x>r.left+r.width/2};label='调整分类顺序';}}
    else if(g.resize){const source=g.sourceColumn||g.node.closest('[data-tc-drop=time]');const date=source.dataset.date;const local=Math.round((y-source.getBoundingClientRect().top)/1.2/15)*15;const absolute=diffDays(date,g.task.date)*DAY+local;let start=g.task.start,end=start+g.task.duration;if(g.resize==='start')start=Math.min(end-15,absolute);else end=Math.max(start+15,absolute);const dayOffset=Math.floor(start/DAY);const next={...g.task,date:addDays(g.task.date,dayOffset),start:((start%DAY)+DAY)%DAY,duration:Math.min(525600,end-start)};next.dateEnd=next.date;g.result=next;label=`${dayLabel(next.date)} ${timeLabel(next)}`;preview(source,next);}
    else if(target){const type=target.dataset.tcDrop;if(type==='time'){const minute=Math.max(0,Math.min(1425,Math.round(((y-target.getBoundingClientRect().top)/1.2-(g.type==='task'?g.offset:0))/15)*15));if(g.type==='create'){const origin=g.originMinute,start=Math.min(origin,minute),duration=Math.max(15,Math.abs(minute-origin));g.result={date:target.dataset.date,start,duration};}else g.result=moveTo(g.task,target.dataset.date,minute);label=`${dayLabel(g.result.date)} ${timeText(g.result.start)} — ${timeText(g.result.start+g.result.duration)}`;preview(target,g.result);}
      else if(g.type==='task'&&type==='day'){g.result=moveTo(g.task,target.dataset.date,g.task.date?undefined:null);label=`安排到 ${dayLabel(target.dataset.date)}`;}
      else if(g.type==='task'&&type==='inbox'){g.result={...g.task,groupId:''};label='放回收集箱 · 取消归类，保留时间';}
      else if(g.type==='task'&&type==='group'){g.result={...g.task,groupId:target.dataset.groupId};label='移动到 '+(state.groups.find(item=>item.id===target.dataset.groupId)?.name||'收集箱');}
      else if(g.type==='task'&&type==='priority'){g.result={...g.task,priority:Number(target.dataset.priorityValue)};label='调整为 '+priorityText[g.result.priority];}
      else if(g.type==='task'&&type==='status'){g.result={...g.task,status:target.dataset.status,done:target.dataset.status==='done',completedAt:target.dataset.status==='done'?Date.now():null};label='移动到'+(g.result.done?'已完成':g.result.status==='doing'?'进行中':'待办');}}
    g.ghost.textContent=label;g.ghost.style.left=Math.min(innerWidth-280,Math.max(8,x+14))+'px';g.ghost.style.top=Math.min(innerHeight-60,Math.max(8,y+16))+'px';if(g.follow){g.follow.style.left=Math.max(0,Math.min(innerWidth-g.follow.offsetWidth,x-(Number.parseFloat(g.follow.style.getPropertyValue('--tc-follow-left'))||0)))+'px';g.follow.style.top=Math.max(0,Math.min(innerHeight-g.follow.offsetHeight,y-(Number.parseFloat(g.follow.style.getPropertyValue('--tc-follow-top'))||0)))+'px';}
  }
  function preview(column,task){root.querySelectorAll('.tc-drop-preview').forEach(n=>n.remove());if(!task.date)return;const day=column.dataset.date,part=segment(task,day);if(part.end<=part.start)return;const el=document.createElement('div');el.className='tc-drop-preview';el.style.top=part.start*1.2+'px';el.style.height=Math.max(18,(part.end-part.start)*1.2)+'px';column.append(el);}
  function autoScroll(){const g=gesture;if(!g?.active)return;const over=document.elementsFromPoint(g.lastX,g.lastY).find(n=>n.closest?.('.tc-time-scroll,.tc-task-list,.tc-collection-tasks'));const scroller=over?.closest('.tc-time-scroll,.tc-task-list,.tc-collection-tasks');if(scroller){const r=scroller.getBoundingClientRect();const delta=g.lastY<r.top+42?-12:g.lastY>r.bottom-42?12:0;if(delta){if(g.edgeDirection!==delta){g.edgeDirection=delta;g.edgeSince=performance.now();}else if(performance.now()-g.edgeSince>180){scroller.scrollTop+=delta;updateGesture(g.lastX,g.lastY);}}else g.edgeDirection=0;}const arrow=document.elementsFromPoint(g.lastX,g.lastY).map(n=>n.closest?.('[data-tc-action=prev],[data-tc-action=next]')).find(Boolean);if(arrow&&!g.resize&&g.type==='task'){if(g.hoverArrow!==arrow.dataset.tcAction){g.hoverArrow=arrow.dataset.tcAction;g.hoverAt=performance.now();}else if(performance.now()-g.hoverAt>700){ui.date=shiftDate(ui.date,g.hoverArrow==='next'?1:-1,ui.view);scrollTop=null;render();g.hoverAt=performance.now();}}else g.hoverArrow=null;g.raf=requestAnimationFrame(autoScroll);}
  function animateTaskMove(change){const before=new Map([...root.querySelectorAll('.tc-task-row[data-tc-task]')].map(n=>[n.dataset.tcTask,n.getBoundingClientRect()]));const result=change();if(result&&!matchMedia('(prefers-reduced-motion: reduce)').matches)root.querySelectorAll('.tc-task-row[data-tc-task]').forEach(n=>{const old=before.get(n.dataset.tcTask);if(!old)return;const next=n.getBoundingClientRect(),x=old.left-next.left,y=old.top-next.top;if(x||y)n.animate([{transform:'translate('+x+'px,'+y+'px)'},{transform:'translate(0,0)'}],{duration:260,easing:'cubic-bezier(.22,1,.36,1)'});});return result;}
  function finishGesture(cancel=false){const g=gesture;if(!g)return;clearTimeout(g.timer);cancelAnimationFrame(g.raf);gesture=null;g.ghost?.remove();g.follow?.remove();g.node?.classList.remove('is-dragging');root.querySelectorAll('.tc-drop-preview,.is-drop-target').forEach(n=>n.classList.contains('tc-drop-preview')?n.remove():n.classList.remove('is-drop-target'));document.body.classList.remove('tc-dragging');root.classList.remove('tc-resizing','tc-inbox-dragging');if(root.hasPointerCapture?.(g.pid))root.releasePointerCapture(g.pid);if(!g.active)return;suppressClick=performance.now()+400;if(cancel||!g.result)return;if(g.type==='create')openEditor(null,g.result);else if(g.type==='group'){const from=state.groups.findIndex(item=>item.id===g.groupId),targetId=g.result.targetId,target=state.groups.findIndex(item=>item.id===targetId),after=g.result.after;if(from>=0&&target>=0&&from!==target)commit(next=>{const [item]=next.groups.splice(from,1);let at=next.groups.findIndex(item=>item.id===targetId);if(after)at++;next.groups.splice(Math.max(0,at),0,item);},'分类顺序已更新');}else if(animateTaskMove(()=>updateTask(g.task.id,g.result,g.resize?'时长已调整':'安排已更新'))){refreshDayDialog();}}
  root.addEventListener('pointerdown',beginGesture,{signal});
  root.addEventListener('wheel',e=>{const board=e.target.closest('.tc-board');if(!board||board.scrollWidth<=board.clientWidth+2)return;const overTasks=e.target.closest('.tc-collection-tasks');if(overTasks&&!e.shiftKey)return;const delta=e.shiftKey?(Math.abs(e.deltaX)>0?e.deltaX:e.deltaY):e.deltaY;if(delta){board.scrollLeft+=delta;e.preventDefault();}},{signal,passive:false});
  window.addEventListener('pointermove',e=>{if(!gesture||e.pointerId!==gesture.pid)return;gesture.lastX=e.clientX;gesture.lastY=e.clientY;if(!gesture.active){const distance=Math.hypot(e.clientX-gesture.x,e.clientY-gesture.y);if(gesture.type==='group'){if(gesture.holdReady)activateGesture();}else{if(gesture.pointerType==='touch'&&distance>9){clearTimeout(gesture.timer);gesture=null;return;}if(distance>5)activateGesture();}}if(gesture?.active){e.preventDefault();updateGesture(e.clientX,e.clientY);}},{signal,passive:false});
